from taf.rfrl.procedures.resources.python.logger import log_step, log_result, log_iteration

from taf.rfrl.procedures.resources.python.counters.core.interface import Core
from taf.rfrl.procedures.resources.python.counters.cells.exceptions import \
    NoRaSetupAttemptsDetected, NoRaSetupCompletionsDetected, InvalidRaMsg3ReceptionsNumber
from taf.rfrl.procedures.resources.python.admin_info_model.admin_info_model import (
    get_mrbts_id_admin,
    get_nrbts_id_admin
)


class CellCounters(Core):
    def __init__(self):
        super(CellCounters, self).__init__()

    def verify_ra_setup_attempts_counters(self, cell_id, n_frames=2):
        """
        Verifies RA Setup Attempts counters (M55306C00001-M55306C00XXX) if there are any increase of values for any
        RA Setup Attempts counter.

        :param cell_id: Cell Id that user wants to perform verification.
        :type cell_id: int/str
        :param n_frames: Number of last frames to be verified
        :type n_frames: int/str
        :return: True if verification finishes with success
        :rtype: boolean
        :raises: NoRaSetupAttemptsDetected if there will bo no increase of value in any of RA Setup Attempts counters
        """
        log_step("RA Setup Attempts counters verification begins...")
        mrbts_id = get_mrbts_id_admin(connection=self.api_connection_alias)
        nrbts_id = get_nrbts_id_admin(connection=self.api_connection_alias)

        try:
            nrach_counters = self.counters["CELLS"][f"NRCELL-{cell_id}"]["NRACH"]
        except KeyError:
            nrach_counters = self.counters[f"MRBTS-{mrbts_id}"][f"NRBTS-{nrbts_id}"][f"NRCELL-{cell_id}"]["NRACH"]

        setup_attempts_counters = self._get_all_ra_setup_attempts(nrach_counters)
        log_step("Found RA Setup Attempts counters in NR Rach Usage object for NRCELL-{0}: \n{1}".
                 format(cell_id, setup_attempts_counters.keys()))

        for setup_attempt, counters in setup_attempts_counters.items():
            log_iteration("Validating {0} counter...".format(setup_attempt))
            last_frames = self._get_n_last_frames(counters, n=n_frames)
            log_step("Read last {0} time frame values: {1}".format(n_frames, last_frames))

            if all(int(value) > 0 for value in last_frames.values()):
                log_result("RA Setup attempts found in last {0} frames of {1} counter, success!".format(n_frames,
                                                                                                        setup_attempt))
                return True

        raise NoRaSetupAttemptsDetected("Couldn't find increase of value in any of RA Setup Attempts counters!")

    def verify_ra_setup_completions(self, cell_id, n_frames=2):
        """
        Verifies RA Setup Completions during number of time frames and cell id provided by user.
        Method verifies M55306C03001 counter if any of values from last n time frames increased.

        :param cell_id: Cell Id that user wants to perform verification.
        :type cell_id: int/str
        :param n_frames: Number of last frames to be verified
        :type n_frames: int/str
        :return: True if verification finishes with success
        :rtype: boolean
        :raises: NoRaSetupCompletionsDetected there will be no increase of value in any of RA Setup Completions
                 counters
        """
        log_step("RA Setup Completions counters verification begins...")
        mrbts_id = get_mrbts_id_admin(connection=self.api_connection_alias)
        nrbts_id = get_nrbts_id_admin(connection=self.api_connection_alias)

        try:
            ra_setup_completions_counters = self.counters["CELLS"][f"NRCELL-{cell_id}"]["NRACH"]['M55306C03001']
        except KeyError:
            ra_setup_completions_counters = self.counters[f"MRBTS-{mrbts_id}"][
                f"NRBTS-{nrbts_id}"][f"NRCELL-{cell_id}"]["NRACH"]['M55306C03001']

        log_step("Found RA Setup Completions counters in NR Rach Usage object for NRCELL-{0}: \n{1}".
                 format(cell_id, ra_setup_completions_counters.keys()))

        last_frames = self._get_n_last_frames(ra_setup_completions_counters, n=n_frames)

        if all(int(value) > 0 for value in last_frames.values()):
            log_result("RA Setup completions found in last {0} frames of M55306C03001 counter, success!".
                       format(n_frames))
            return True

        raise NoRaSetupCompletionsDetected("Couldn't find increase of value in RA Setup Completions counter!")

    def verify_ra_msg3_receptions(self, cell_id, expected_value, n_frames=2):
        """
        Verifies if RA Msg3 Receptions in M55306C03001 counter for provided cell id equals to expected value provided
        by user.

        :param cell_id: Cell Id that user wants to perform verification.
        :type cell_id: int/str
        :param expected_value: Expected value of RA Msg3 Receptions provided by user
        :type expected_value: int/str
        :param n_frames: Number of last frames to be verified
        :type n_frames: int/str
        :return: True if verification finishes with success
        :rtype: boolean
        :raises: InvalidRaMsg3ReceptionsNumber if there will be mismatch between sum of detected RA Msg3 Reception
                 and expected value provided by user
        """
        log_step("RA msg3 receptions counters verification begins...")
        mrbts_id = get_mrbts_id_admin(connection=self.api_connection_alias)
        nrbts_id = get_nrbts_id_admin(connection=self.api_connection_alias)
        try:
            ra_msg3_receptions = self.counters["CELLS"][f"NRCELL-{cell_id}"]["NRACH"]['M55306C06001']
        except KeyError:
            ra_msg3_receptions = self.counters[f"MRBTS-{mrbts_id}"][
                f"NRBTS-{nrbts_id}"][f"NRCELL-{cell_id}"]["NRACH"]['M55306C06001']

        log_result("Found RA Msg3 Reception counters: {0}".format(ra_msg3_receptions))

        last_frames = self._get_n_last_frames(ra_msg3_receptions, n=n_frames)
        sum_of_msg_receptions = sum([int(value) for value in last_frames.values()])
        log_result("Calculated sum of RA msg3 receptions of last {0} time frames: {1}".format(n_frames,
                                                                                              sum_of_msg_receptions))

        if not sum_of_msg_receptions == int(expected_value):
            raise InvalidRaMsg3ReceptionsNumber("Sum of found RA msg3 receptions in M55306C06001 counter ({0})"
                                                " is not consistent with expected value ({1})!".
                                                format(sum_of_msg_receptions, expected_value))
        return True

    @staticmethod
    def _get_all_ra_setup_attempts(nrach_counters):
        setup_attempts = [counter for counter in nrach_counters.keys() if 'M55306C00' in counter]
        return {setup_counter: nrach_counters[setup_counter] for setup_counter in setup_attempts}
